def separate_paren_groups(paren_string: str) -> List[str]:
    # Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Loop through the input string and identify each group of nested parentheses
    groups = []
    start = 0
    count = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            count += 1
            if count == 1:
                start = i
        elif char == ')':
            count -= 1
            if count == 0:
                groups.append(paren_string[start:i+1])

    # Check if each group is balanced by counting the number of open and close parentheses
    for group in groups:
        if group.count('(') != group.count(')'):
            raise ValueError("Unbalanced parentheses in group: {}".format(group))

    # Store each separated group in a list
    return groups

