def get_row(lst, x):
    coordinates = []

    for i, row in enumerate(lst):
        for j, num in enumerate(row):
            if num == x:
                coordinates.append((i, j))

    coordinates.sort(key=lambda coord: coord[0])  # Sort by rows in ascending order
    for i in range(len(lst)):
