def smallest_change(arr):
    def is_palindrome(sub_arr):
        return sub_arr == sub_arr[::-1]

    def count_changes(sub_arr):
        changes = 0
        for i in range(len(sub_arr) // 2):
            if sub_arr[i] != sub_arr[-i - 1]:
                changes += 1
        return changes

    if len(arr) <= 1:
        return 0

    middle = len(arr) // 2
    left_sub_arr = arr[:middle]
    right_sub_arr = arr[middle + len(arr) % 2:]

    changes_left = count_changes(left_sub_arr)
    changes_right = count_changes(right_sub_arr)

    return min(changes_left, changes_right)

